def identity_matrix(n: int) -> List[List[int]]:
    """Create n×n identity matrix."""
    return [[1 if i == j else 0 for j in range(n)] for i in range(n)]


def hstack_matrices(A: List[List[int]], B: List[List[int]]) -> List[List[int]]:
    """Horizontally stack two matrices [A | B]."""
    assert len(A) == len(B), "Matrices must have same number of rows"
    return [row_a + row_b for row_a, row_b in zip(A, B)]


def get_matrix_transpose(A: List[List[int]]) -> List[List[int]]:
    """Transpose matrix A."""
    if not A:
        return []
    return [[A[i][j] for i in range(len(A))] for j in range(len(A[0]))]


def matrix_multiply_binary(A: List[List[int]], B: List[List[int]]) -> List[List[int]]:
    """
    Multiply two matrices in binary (mod 2) arithmetic.

    Args:
        A: Matrix of shape (m, n)
        B: Matrix of shape (n, p)

    Returns:
        Result matrix of shape (m, p) with all elements mod 2
    """
    if not A or not B:
        return []

    m, n = len(A), len(A[0])
    n2, p = len(B), len(B[0])

    assert n == n2, f"Matrix dimensions don't match: ({m},{n}) × ({n2},{p})"

    result = []
    for i in range(m):
        row = []
        for j in range(p):
            # Dot product of A[i,:] and B[:,j], mod 2
            val = sum(A[i][k] * B[k][j] for k in range(n)) % 2
            row.append(val)
        result.append(row)

    return result


def are_matrices_equal_binary(A: List[List[int]], B: List[List[int]]) -> bool:
    """Check if two matrices are equal (element-wise)."""
    if len(A) != len(B):
        return False
    for row_a, row_b in zip(A, B):
        if len(row_a) != len(row_b):
            return False
        if row_a != row_b:
            return False
    return True


