def test_forward_ubp_mapping():
    """
    Test Forward UBP Mapping: Seed → Observable → Recovered Seed

    This test validates 100% closure/perfect reconstruction across
    a spectrum of test frequencies.
    """
    print("\n" + "="*70)
    print("UBP CORE VERIFICATION TEST")
    print("="*70)
    print("\nTest: Forward UBP Mapping (Seed → Observable → Recovered Seed)")
    print("-" * 70)

    # Test spectrum: 10 frequencies from 1 Hz to H-alpha line (456 THz)
    test_frequencies = [
        1.0,                # 1 Hz - Extremely low frequency
        60.0,               # 60 Hz - Power line frequency
        440.0,              # 440 Hz - Musical note A4
        1e6,                # 1 MHz - Radio frequency
        1e9,                # 1 GHz - Microwave
        5e14,               # 500 THz - Visible light (orange)
        4.5677e14,          # 456.77 THz - H-alpha line
        1e12,               # 1 THz - Far infrared
        1e8,                # 100 MHz - FM radio
        2.4e9,              # 2.4 GHz - WiFi
    ]

    perfect_closures = 0
    total_tests = len(test_frequencies)

    print(f"\n{'Frequency (Hz)':<20} {'Seed':<12} {'Recovered':<12} {'Closure':<10} {'Status'}")
    print("-" * 70)

    for freq in test_frequencies:
        # Step 1: Convert frequency to seed
        seed = observable_to_seed(freq)

        # Step 2: Create OffBit from seed
        original = seed_to_observable(seed)

        # Step 3: Observe OffBit to get signature
        signature = observe_offbit(original, block_size=6, rotate_by=5)

        # Step 4: Reconstruct from signature
        reconstructed = reconstruct_from_signature(signature, known_rotate_by=5)

        # Step 5: Extract recovered seed
        recovered_seed = int(reconstructed.value) & ((1 << 24) - 1)

        # Step 6: Compute closure distance
        closure = closure_distance(original, reconstructed)

        # Determine status
        if closure == 0 and seed == recovered_seed:
            status = "✓ PERFECT"
            perfect_closures += 1
        else:
            status = "✗ FAILED"

        # Format frequency for display
        if freq >= 1e12:
            freq_str = f"{freq/1e12:.2f} THz"
        elif freq >= 1e9:
            freq_str = f"{freq/1e9:.2f} GHz"
        elif freq >= 1e6:
            freq_str = f"{freq/1e6:.2f} MHz"
        elif freq >= 1e3:
            freq_str = f"{freq/1e3:.2f} kHz"
        else:
            freq_str = f"{freq:.2f} Hz"

        print(f"{freq_str:<20} {seed:<12} {recovered_seed:<12} {closure:<10} {status}")

    print("-" * 70)
    print(f"\nResults: {perfect_closures}/{total_tests} perfect closures")
    print("=" * 70)

    if perfect_closures == total_tests:
        print("\n✓ SUCCESS: 100% closure confirmed - Perfect reconstruction!")
        print("All necessary classes (OffBit, Signature, GolayCodeword, etc.) are available.")
        return True
    else:
        print("\n✗ FAILURE: Not all tests achieved perfect closure")
        return False


